-- Textos da home e traduções da trajetória, nos 6 idiomas.
-- Gerado a partir do conteúdo já publicado no site.
-- Só prosa é traduzida; clubes, siglas, anos e números são cópia da raiz.

BEGIN;

-- 1) Apresentação do topo da home (Admin > Estatísticas).
--    O merge por idioma preserva as traduções de characteristics já existentes.
UPDATE player_stats SET
  hero_text = 'Ambidestra, finalização precisa e leitura de jogo rara. A nova geração do ataque brasileiro — em campo na Alemanha, convocada pela seleção.',
  translations = COALESCE(translations, '{}'::jsonb)
    || jsonb_build_object('pt', COALESCE(translations->'pt', '{}'::jsonb) || jsonb_build_object('hero_text', 'Ambidestra, finalização precisa e leitura de jogo rara. A nova geração do ataque brasileiro — em campo na Alemanha, convocada pela seleção.'))
    || jsonb_build_object('en', COALESCE(translations->'en', '{}'::jsonb) || jsonb_build_object('hero_text', 'Two-footed, clinical finishing and rare game vision. The new generation of Brazilian attack — playing in Germany, called up by the national team.'))
    || jsonb_build_object('es', COALESCE(translations->'es', '{}'::jsonb) || jsonb_build_object('hero_text', 'Ambidiestra, definición precisa y una lectura de juego poco común. La nueva generación del ataque brasileño — jugando en Alemania, convocada por la selección.'))
    || jsonb_build_object('de', COALESCE(translations->'de', '{}'::jsonb) || jsonb_build_object('hero_text', 'Beidfüßig, präziser Abschluss und seltenes Spielverständnis. Die neue Generation des brasilianischen Angriffs — in Deutschland am Ball, für die Nationalmannschaft nominiert.'))
    || jsonb_build_object('fr', COALESCE(translations->'fr', '{}'::jsonb) || jsonb_build_object('hero_text', 'Ambidextre, finition précise et lecture du jeu rare. La nouvelle génération de l''attaque brésilienne — sur les terrains en Allemagne, convoquée en sélection.'))
    || jsonb_build_object('it', COALESCE(translations->'it', '{}'::jsonb) || jsonb_build_object('hero_text', 'Ambidestra, finalizzazione precisa e rara lettura del gioco. La nuova generazione dell''attacco brasiliano — in campo in Germania, convocata in nazionale.'))
;

-- 2) Trajetória: um UPDATE por card ativo.
UPDATE trajectory_cards SET translations = '{"pt":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"Principal","items":["2025/2026","26","25","8","Artilheira da Taça de Portugal com 12 gols","Artilheira dos oito clubes na fase campeão com 13 gols"]}}},"en":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"First team","items":["2025/2026","26","25","8","Top scorer of the Portuguese Cup with 12 goals","Top scorer among the eight clubs in the championship stage with 13 goals"]}}},"es":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"Primer equipo","items":["2025/2026","26","25","8","Máxima goleadora de la Copa de Portugal con 12 goles","Máxima goleadora de los ocho clubes en la fase de campeón con 13 goles"]}}},"de":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"Erste Mannschaft","items":["2025/2026","26","25","8","Torschützenkönigin des portugiesischen Pokals mit 12 Toren","Torschützenkönigin der acht Vereine in der Meisterrunde mit 13 Toren"]}}},"fr":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"Équipe première","items":["2025/2026","26","25","8","Meilleure buteuse de la Coupe du Portugal avec 12 buts","Meilleure buteuse des huit clubs lors de la phase championnat avec 13 buts"]}}},"it":{"title":"Gil Vicente ","cats":{"t5mwef19c":{"name":"Prima squadra","items":["2025/2026","26","25","8","Capocannoniera della Coppa del Portogallo con 12 gol","Capocannoniera degli otto club nella fase campionato con 13 gol"]}}}}'::jsonb WHERE id = '2e48ed5f-48e0-4150-adcb-67d73bc87c16';
