-- 3) As observações do Gil Vicente estão em italiano no campo original, então
--    apareciam em italiano também em português. Passam para o PT.
UPDATE trajectory_cards SET stats_data = jsonb_set(jsonb_set(stats_data::jsonb,
    '{0,items,4,text}', to_jsonb('Artilheira da Taça de Portugal com 12 gols'::text)),
    '{0,items,5,text}', to_jsonb('Artilheira dos oito clubes na fase campeão com 13 gols'::text))
  WHERE id = '2e48ed5f-48e0-4150-adcb-67d73bc87c16';

-- 4) Período do SGS Essen U-16, pelo mesmo motivo.
UPDATE trajectory_cards SET stats_data = jsonb_set(stats_data::jsonb,
